PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT (COUNT(?modified) AS ?modificationCount)
WHERE {
  ?ontology dcterms:modified ?modified .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX s4envi: <http://example.org/s4envi#>

SELECT (COUNT(?device) AS ?count)
WHERE {
  ?device s4envi:hasFlash "true"^^xsd:boolean ;
          s4envi:hasProjectionAngle ?angle ;
          s4envi:hasCreationDate ?date .
  FILTER(?angle < 30 && ?date < "2023-01-01T00:00:00"^^xsd:dateTime)
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX s4envi: <http://example.org/s4envi#>

SELECT (COUNT(?device) AS ?numberOfDevices)
WHERE {
  ?device s4envi:hasTag "specific_tag"^^xsd:string ;
          s4envi:hasShield "true"^^xsd:boolean ;
          s4envi:hasCreationDate ?creationDate .
  FILTER(?creationDate >= "start_date"^^xsd:dateTime && ?creationDate <= "end_date"^^xsd:dateTime)
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX s4envi: <http://www.wurvoc.org/vocabularies/om-1.8/>

SELECT (COUNT(DISTINCT ?unit) AS ?numberOfLengthUnits)
WHERE {
  ?unit rdf:type s4envi:LengthUnit .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX s4envi: <http://example.org/s4envi/>

SELECT (COUNT(?unit) AS ?frequencyUnitCount)
WHERE {
    ?unit rdf:type s4envi:FrequencyUnit .
}

SELECT ?unit ?type
WHERE {
  ?unit rdf:type s4envi:LengthUnit .
  ?unit rdf:type ?type .
  FILTER(?type = s4envi:LengthUnit || ?type = owl:NamedIndividual)
}

# Write your query here.
SELECT ?license
WHERE {
  <https://saref.etsi.org/saref4envi/> dcterms:license ?license
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX saref: <https://saref.etsi.org/core/>
PREFIX s4envi: <http://example.org/s4envi#>

SELECT ?measurementType ?category
WHERE {
  {
    ?measurementType rdfs:subClassOf saref:Measurement .
    BIND("Measurement" AS ?category)
  }
  UNION
  {
    ?measurementType rdfs:subClassOf saref:UnitOfMeasure .
    BIND("UnitOfMeasure" AS ?category)
  }
}
